cat > test.mjs <<'EOF'
import { reserve } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-inv-g4-3/bot.mjs";
import { mkdtempSync, utimesSync, mkdirSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
const run = promisify(execFile);
const assert = (c, m) => { if (!c) throw new Error("FAIL: " + m); console.log("ok -", m); };

process.env.STATE_DIR = join(mkdtempSync(join(tmpdir(), "bot-")), "nested", "state");
const T0 = new Date("2026-10-23T10:00:00.000Z");
const at = (ms) => new Date(T0.getTime() + ms);
const H = 3600e3;

// 1. five allowed across mixed channels, sixth blocked
const chans = ["sms", "push", "chat", "sms", "push"];
for (let i = 0; i < 5; i++) {
  const r = await reserve("u1", chans[i], at(i * 1000));
  assert(r.allowed === true && r.retryAt === null, `u1 send ${i + 1} allowed (${chans[i]})`);
}
const b = await reserve("u1", "chat", at(10_000));
assert(b.allowed === false, "u1 sixth send blocked");
assert(b.retryAt.getTime() === T0.getTime() + 24 * H, "retryAt = oldest send + 24h");
console.log("   reason:", b.reason);

// 2. blocked call counts nothing: still blocked, same retryAt
const b2 = await reserve("u1", "sms", at(20_000));
assert(!b2.allowed && b2.retryAt.getTime() === b.retryAt.getTime(), "repeated block does not count");

// 3. other customer unaffected
const o = await reserve("u2", "push", at(30_000));
assert(o.allowed, "u2 unaffected by u1");

// 4. one ms before expiry still blocked; at exactly retryAt allowed
const before = await reserve("u1", "sms", new Date(b.retryAt.getTime() - 1));
assert(!before.allowed, "u1 blocked 1ms before retryAt");
const after = await reserve("u1", "sms", b.retryAt);
assert(after.allowed, "u1 allowed exactly at retryAt");
// now 5 live sends remain (t1..t4 + new); count=5 so next retry is the oldest remaining
const nextBlock = await reserve("u1", "sms", new Date(b.retryAt.getTime() + 1));
assert(!nextBlock.allowed && nextBlock.retryAt.getTime() === T0.getTime() + 1000 + 24 * H, "after sliding, retryAt follows the next-oldest send");

// 5. invalid input rejected
for (const bad of [["", "sms", new Date()], ["u", "email", new Date()], ["u", "sms", "now"], ["u", "sms", new Date("x")]]) {
  let threw = false;
  try { await reserve(...bad); } catch { threw = true; }
  assert(threw, `rejects bad input ${JSON.stringify(bad[1])} ${String(bad[2])}`);
}

// 6. stale lock from a crashed process is broken
const dir = process.env.STATE_DIR;
const crypto = await import("node:crypto");
const key = crypto.createHash("sha256").update("u3").digest("hex");
mkdirSync(join(dir, "locks", `${key}.lock`), { recursive: true });
const old = new Date(Date.now() - 60_000);
utimesSync(join(dir, "locks", `${key}.lock`), old, old);
const s = await reserve("u3", "sms", at(0));
assert(s.allowed, "stale lock broken, send allowed");

// 7. concurrency across real processes: 8 processes x 10 calls, same user, same instant
const outs = await Promise.all(Array.from({ length: 8 }, () =>
  run("node", ["/tmp/bot-check/worker.mjs", "u4", "10", T0.toISOString()], { env: process.env })
    .then((r) => r.stdout.trim())));
const allowed = outs.join("").split("").filter((c) => c === "A").length;
assert(allowed === 5, `concurrent processes: exactly 5 of 80 allowed (got ${allowed})`);

// 8. state survives restart: a new process sees the earlier sends
const again = await run("node", ["/tmp/bot-check/worker.mjs", "u4", "1", T0.toISOString()], { env: process.env });
assert(again.stdout.trim() === "D", "new process sees prior sends after restart");
console.log("ALL CHECKS PASSED");
EOF
